/*
 * A211685  Prime numbers > 1000 such that all the substrings of length >= 3
 *          are primes (substrings with leading '0' are considered to be
 *          nonprime).
 * https://oeis.org/A211685
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, base, full
 * Formula:   Sequence A211685 is generated by testing primes >1000 for the
 *            property that every decimal substring of length ≥3 (with no
 *            leading 0) is also prime. This code performs an on‑first‑call
 *            search up to the known last term (349199) and caches the results
 * Range:     u8 none, u16 n <= 61, u32 n <= 63, u64 n <= 63, u128 n <= 63,
 *            big any n
 * Helpers:   local_digits
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include "../utils/local_digits.h"

/* Local primality test (fast enough for numbers ≤ 350000). */
static bool local_is_prime(idx_t n)
{
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    for (idx_t d = 3; d * d <= n; d += 2)
        if (n % d == 0) return false;
    return true;
}

/* Return the n‑th term of A211685. */
seq_t a(idx_t n)
{
    /* Static cache for memoisation. */
    static seq_t cache[70];          /* 70 > 63 to be safe. */
    static size_t cache_len = 0;
    static bool initialized = false;

    /* Maximum value for the sequence (last term = 349199). */
    const idx_t upper_limit = 350000;   /* one unit above the last known. */

    if (!initialized) {
        /* Build the cache on first call. */
        for (idx_t candidate = 1001; candidate <= upper_limit; ++candidate) {
            if (!local_is_prime(candidate)) continue;

            /* Extract digits into array most significant first. */
            int len = local_digits(candidate);
            unsigned char digs[20];   /* 20 > enough for any number in range. */
            idx_t temp = candidate;
            for (int i = len - 1; i >= 0; --i) {
                digs[i] = temp % 10;
                temp /= 10;
            }

            bool ok = true;
            for (int i = 0; i + 3 <= len && ok; ++i) {
                if (digs[i] == 0) {   /* leading zero makes substring non‑prime */
                    ok = false;
                    break;
                }
                idx_t sub = 0;
                for (int j = i; j < len; ++j) {
                    sub = sub * 10 + digs[j];
                    if (j - i + 1 >= 3 && !local_is_prime(sub)) {
                        ok = false;
                        break;
                    }
                }
            }

            if (ok) {
                cache[cache_len++] = (seq_t)candidate;
                if (cache_len == 63)  /* all known terms collected */
                    break;
            }
        }
        initialized = true;
    }

    /* Return the requested term (1‑based indexing). */
    if (n == 0) return 0;                     /* undefined below offset */
    if (n <= cache_len) return cache[n - 1];
    return 0;                                 /* undefined for n beyond known terms */
}
